export const MIGRATIONS = [{"name":"0001_foundation.sql","sql":"-- =============================================================================\n-- 0001  Foundation: extensions, app schema, identity helpers\n-- =============================================================================\n-- The helpers below read the JWT claims GUC that PostgREST/Supabase sets on\n-- every request. Reading the GUC directly (rather than auth.uid()) means the\n-- exact same policies run under `psql` in tests, where we set the GUC by hand.\n-- =============================================================================\n\n-- gen_random_uuid() is core Postgres since 13, so pgcrypto is not required.\n-- Avoiding it keeps the schema loadable anywhere Postgres runs -- including\n-- WASM builds, where the contrib extension is unavailable.\ndo $$\nbegin\n  if current_setting('server_version_num')::int < 130000 then\n    raise exception 'PostgreSQL 13 or newer is required (gen_random_uuid)';\n  end if;\nend $$;\n\n-- Needed for the exclusion constraints that stop fiscal periods overlapping.\ncreate extension if not exists \"btree_gist\";\n\ncreate schema if not exists app;\ncomment on schema app is 'Helper functions and enums. Never contains business rows.';\n\n-- ---------------------------------------------------------------------------\n-- Identity\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.current_user_id()\nreturns uuid\nlanguage sql\nstable\nas $$\n  select nullif(\n    current_setting('request.jwt.claims', true)::jsonb ->> 'sub',\n    ''\n  )::uuid\n$$;\ncomment on function app.current_user_id is\n  'Authenticated user id from the request JWT, or NULL when unauthenticated.';\n\n-- ---------------------------------------------------------------------------\n-- Enums\n-- ---------------------------------------------------------------------------\n\n-- Mirrors the six roles proven in AZ Accounting v1.\ncreate type app.user_role as enum (\n  'owner',          -- المالك        full control, including settings and users\n  'manager',        -- المدير        full operational control\n  'supervisor',     -- المشرف        sees everything, changes nothing\n  'data_entry',     -- موظف الإدخال  drafts documents, cannot post\n  'reviewer',       -- المراجِع      approves or rejects drafted documents\n  'viewer',         -- مطّلِع        read-only on parties and their balances\n  'invoice_viewer'  -- عرض الفواتير  read-only on documents alone\n);\n\ncreate type app.account_type as enum (\n  'asset', 'liability', 'equity', 'revenue', 'expense'\n);\n\ncreate type app.normal_balance as enum ('debit', 'credit');\n\ncreate type app.document_type as enum (\n  'sales_invoice',      -- فاتورة مبيعات\n  'sales_credit_note',  -- إشعار دائن\n  'sales_debit_note',   -- إشعار مدين\n  'purchase_invoice',   -- فاتورة مشتريات\n  'receipt',            -- إيصال قبض\n  'payment'             -- إيصال صرف\n);\n\ncreate type app.document_status as enum (\n  'draft',           -- editable by its author\n  'pending_review',  -- editable by author, awaiting reviewer\n  'rejected',        -- editable by author, reviewer sent it back\n  'posted',          -- IMMUTABLE. Has hit the ledger.\n  'cancelled'        -- IMMUTABLE. Reversed by a linked entry.\n);\n\ncreate type app.party_type as enum ('business', 'person', 'foreigner');\n\n-- ---------------------------------------------------------------------------\n-- Shared column behaviour\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.touch_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\n-- Rounds to 5 decimal places, the precision the ETA schema expects on amounts.\ncreate or replace function app.round5(v numeric)\nreturns numeric\nlanguage sql\nimmutable\nas $$\n  select round(coalesce(v, 0), 5)\n$$;\n"},{"name":"0002_tenancy.sql","sql":"-- =============================================================================\n-- 0002  Tenancy: companies, branches, users\n-- =============================================================================\n\ncreate table tenant (\n  id                    uuid primary key default gen_random_uuid(),\n  name                  text not null,\n  legal_name_ar         text not null,\n  legal_name_en         text,\n\n  -- Egyptian Tax Authority issuer identity. Required before any e-invoice can\n  -- be submitted; nullable so a tenant can be created and configured later.\n  tax_registration_no   text,          -- الرقم الضريبي\n  commercial_reg_no     text,          -- السجل التجاري\n  eta_client_id         text,\n  eta_client_secret     text,          -- server-side only; RLS denies all reads\n  eta_environment       text not null default 'preprod'\n                          check (eta_environment in ('preprod', 'production')),\n\n  base_currency         char(3) not null default 'EGP',\n  vat_registered        boolean not null default false,\n\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now(),\n\n  constraint tenant_trn_format\n    check (tax_registration_no is null or tax_registration_no ~ '^[0-9]{9}$')\n);\n\ncomment on column tenant.tax_registration_no is\n  'Egyptian tax registration number, 9 digits. Required for ETA submission.';\n\ncreate table branch (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  code          text not null,\n  name          text not null,\n\n  -- ETA requires a full structured address on the issuing branch.\n  country       char(2) not null default 'EG',\n  governorate   text,                  -- المحافظة\n  city          text,\n  street        text,\n  building_no   text,\n  postal_code   text,\n  activity_code text,                  -- كود النشاط\n\n  is_active     boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n\n  unique (tenant_id, code)\n);\n\ncreate table app_user (\n  -- Matches auth.users.id on Supabase. No FK, so the schema also loads on a\n  -- plain Postgres instance for testing.\n  id            uuid primary key,\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  branch_id     uuid references branch(id) on delete set null,\n\n  username      text not null,\n  full_name     text not null,\n  role          app.user_role not null,\n\n  -- Carried over from AZ Accounting: a manager approves each new login, and\n  -- staff sessions are cut off outside working hours.\n  is_approved   boolean not null default false,\n  approved_by   uuid references app_user(id),\n  approved_at   timestamptz,\n  is_active     boolean not null default true,\n  session_ends_at_hour smallint\n                  check (session_ends_at_hour between 0 and 23),\n\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n\n  unique (tenant_id, username)\n);\n\ncreate index app_user_tenant_idx on app_user (tenant_id) where is_active;\n\ncreate trigger tenant_touch   before update on tenant   for each row execute function app.touch_updated_at();\ncreate trigger branch_touch   before update on branch   for each row execute function app.touch_updated_at();\ncreate trigger app_user_touch before update on app_user for each row execute function app.touch_updated_at();\n\n-- ---------------------------------------------------------------------------\n-- Tenant + role resolution, used by every RLS policy below.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.current_tenant_id()\nreturns uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = public, app\nas $$\n  select u.tenant_id\n  from app_user u\n  where u.id = app.current_user_id()\n    and u.is_active\n    and u.is_approved\n$$;\n\ncreate or replace function app.current_role()\nreturns app.user_role\nlanguage sql\nstable\nsecurity definer\nset search_path = public, app\nas $$\n  select u.role\n  from app_user u\n  where u.id = app.current_user_id()\n    and u.is_active\n    and u.is_approved\n$$;\n\ncreate or replace function app.has_role(variadic roles app.user_role[])\nreturns boolean\nlanguage sql\nstable\nas $$\n  select app.current_role() = any(roles)\n$$;\n\n-- Anyone who may see the full financial picture.\ncreate or replace function app.can_read_ledger()\nreturns boolean\nlanguage sql\nstable\nas $$\n  select app.has_role('owner', 'manager', 'supervisor', 'reviewer', 'viewer')\n$$;\n\n-- Anyone who may move a document into the ledger.\ncreate or replace function app.can_post()\nreturns boolean\nlanguage sql\nstable\nas $$\n  select app.has_role('owner', 'manager', 'reviewer')\n$$;\n"},{"name":"0003_accounts_and_periods.sql","sql":"-- =============================================================================\n-- 0003  Chart of accounts and the fiscal calendar\n-- =============================================================================\n\ncreate table account (\n  id              uuid primary key default gen_random_uuid(),\n  tenant_id       uuid not null references tenant(id) on delete cascade,\n  parent_id       uuid references account(id) on delete restrict,\n\n  code            text not null,\n  name_ar         text not null,\n  name_en         text,\n  type            app.account_type not null,\n  normal_balance  app.normal_balance not null,\n\n  -- Only leaf accounts take postings; parents exist to roll up.\n  is_postable     boolean not null default true,\n  is_active       boolean not null default true,\n  currency        char(3),   -- NULL = tenant base currency\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  unique (tenant_id, code)\n);\n\ncreate index account_tenant_idx on account (tenant_id, code);\ncreate index account_parent_idx on account (parent_id);\n\ncreate trigger account_touch before update on account\n  for each row execute function app.touch_updated_at();\n\n-- A parent account must never carry postings directly.\ncreate or replace function app.assert_account_leaf()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if exists (select 1 from account where parent_id = new.id) and new.is_postable then\n    raise exception\n      'account % has children and cannot be postable', new.code\n      using errcode = 'check_violation';\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger account_leaf_check before insert or update on account\n  for each row execute function app.assert_account_leaf();\n\n-- ---------------------------------------------------------------------------\n-- Fiscal calendar. Posting into a closed period is refused at the database.\n-- ---------------------------------------------------------------------------\n\ncreate table fiscal_year (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null references tenant(id) on delete cascade,\n  name        text not null,\n  starts_on   date not null,\n  ends_on     date not null,\n  is_closed   boolean not null default false,\n  created_at  timestamptz not null default now(),\n\n  unique (tenant_id, name),\n  constraint fiscal_year_range check (ends_on > starts_on),\n\n  -- No two fiscal years for one tenant may overlap.\n  constraint fiscal_year_no_overlap\n    exclude using gist (\n      tenant_id with =,\n      daterange(starts_on, ends_on, '[]') with &&\n    )\n);\n\ncreate table fiscal_period (\n  id              uuid primary key default gen_random_uuid(),\n  tenant_id       uuid not null references tenant(id) on delete cascade,\n  fiscal_year_id  uuid not null references fiscal_year(id) on delete cascade,\n  name            text not null,\n  starts_on       date not null,\n  ends_on         date not null,\n  is_closed       boolean not null default false,\n  closed_at       timestamptz,\n  closed_by       uuid references app_user(id),\n\n  constraint fiscal_period_range check (ends_on >= starts_on),\n  constraint fiscal_period_no_overlap\n    exclude using gist (\n      tenant_id with =,\n      daterange(starts_on, ends_on, '[]') with &&\n    )\n);\n\ncreate index fiscal_period_lookup_idx\n  on fiscal_period (tenant_id, starts_on, ends_on);\n\n-- Resolves the period a date falls in, and refuses if it is closed or missing.\ncreate or replace function app.open_period_for(p_tenant uuid, p_on date)\nreturns uuid\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_period fiscal_period%rowtype;\nbegin\n  select * into v_period\n  from fiscal_period\n  where tenant_id = p_tenant\n    and p_on between starts_on and ends_on;\n\n  if not found then\n    raise exception 'no fiscal period covers %', p_on\n      using errcode = 'check_violation';\n  end if;\n\n  if v_period.is_closed then\n    raise exception 'fiscal period % is closed', v_period.name\n      using errcode = 'check_violation';\n  end if;\n\n  return v_period.id;\nend;\n$$;\n"},{"name":"0004_ledger.sql","sql":"-- =============================================================================\n-- 0004  The ledger. Append-only, always balanced, never edited.\n-- =============================================================================\n-- Two invariants are enforced here by the database itself, so that no\n-- application bug and no direct SQL can violate them:\n--\n--   1. Every journal entry balances: SUM(debit) = SUM(credit).\n--   2. A journal entry, once written, is never updated or deleted.\n--      Corrections happen by writing a reversing entry.\n--\n-- Invariant 2 is what makes the system auditable, and it is also a legal\n-- requirement once a document has been cleared by the Tax Authority.\n-- =============================================================================\n\ncreate table journal_entry (\n  id               uuid primary key default gen_random_uuid(),\n  tenant_id        uuid not null references tenant(id) on delete cascade,\n  branch_id        uuid references branch(id),\n  fiscal_period_id uuid not null references fiscal_period(id),\n\n  entry_no         bigint not null,\n  entry_date       date not null,\n  memo_ar          text,\n  memo_en          text,\n\n  -- What caused this entry. Set for entries generated by posting a document;\n  -- NULL for manual journals.\n  source_doc_type  app.document_type,\n  source_doc_id    uuid,\n\n  -- Set when this entry exists to reverse another one.\n  reverses_entry_id uuid references journal_entry(id),\n\n  posted_by        uuid not null references app_user(id),\n  approved_by      uuid references app_user(id),\n  posted_at        timestamptz not null default now(),\n\n  unique (tenant_id, entry_no),\n  constraint journal_entry_no_self_reversal\n    check (reverses_entry_id is distinct from id)\n);\n\ncreate index journal_entry_period_idx on journal_entry (tenant_id, fiscal_period_id);\ncreate index journal_entry_date_idx   on journal_entry (tenant_id, entry_date);\ncreate index journal_entry_source_idx on journal_entry (source_doc_id)\n  where source_doc_id is not null;\n-- An entry may only be reversed once.\ncreate unique index journal_entry_one_reversal_idx\n  on journal_entry (reverses_entry_id) where reverses_entry_id is not null;\n\ncreate table journal_line (\n  id             uuid primary key default gen_random_uuid(),\n  entry_id       uuid not null references journal_entry(id) on delete restrict,\n  tenant_id      uuid not null references tenant(id) on delete cascade,\n  line_no        integer not null,\n\n  account_id     uuid not null references account(id) on delete restrict,\n  party_id       uuid,          -- FK added in 0005, once party exists\n  branch_id      uuid references branch(id),\n\n  debit          numeric(18,5) not null default 0,\n  credit         numeric(18,5) not null default 0,\n\n  -- Foreign-currency support. amount_base is always in the tenant's base\n  -- currency and is what debit/credit above hold; the original is kept beside\n  -- it. EGP volatility makes this worth carrying from day one.\n  currency       char(3) not null default 'EGP',\n  fx_rate        numeric(18,8) not null default 1,\n  amount_foreign numeric(18,5),\n\n  memo           text,\n\n  unique (entry_id, line_no),\n  constraint journal_line_non_negative check (debit >= 0 and credit >= 0),\n  constraint journal_line_one_side      check ((debit = 0) <> (credit = 0)),\n  constraint journal_line_fx_positive   check (fx_rate > 0)\n);\n\ncomment on constraint journal_line_one_side on journal_line is\n  'A line is either a debit or a credit, never both and never neither.';\n\ncreate index journal_line_entry_idx   on journal_line (entry_id);\ncreate index journal_line_account_idx on journal_line (tenant_id, account_id);\ncreate index journal_line_party_idx   on journal_line (tenant_id, party_id)\n  where party_id is not null;\n\n-- ---------------------------------------------------------------------------\n-- Invariant 1: entries balance. Deferred so that an entry can be assembled\n-- line by line inside a transaction and is only judged at COMMIT.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.assert_entry_balanced()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_entry uuid := coalesce(new.entry_id, old.entry_id);\n  v_debit  numeric(18,5);\n  v_credit numeric(18,5);\n  v_count  integer;\nbegin\n  select coalesce(sum(debit), 0), coalesce(sum(credit), 0), count(*)\n    into v_debit, v_credit, v_count\n  from journal_line\n  where entry_id = v_entry;\n\n  -- The entry was deleted wholesale inside this transaction; nothing to check.\n  if v_count = 0 then\n    return null;\n  end if;\n\n  if v_count < 2 then\n    raise exception 'journal entry % has % line(s); at least 2 are required',\n      v_entry, v_count\n      using errcode = 'check_violation';\n  end if;\n\n  if v_debit <> v_credit then\n    raise exception\n      'journal entry % is out of balance: debit %, credit %, difference %',\n      v_entry, v_debit, v_credit, (v_debit - v_credit)\n      using errcode = 'check_violation';\n  end if;\n\n  return null;\nend;\n$$;\n\ncreate constraint trigger journal_line_balanced\n  after insert or update or delete on journal_line\n  deferrable initially deferred\n  for each row execute function app.assert_entry_balanced();\n\n-- ---------------------------------------------------------------------------\n-- Invariant 2: append-only. No UPDATE, no DELETE, ever.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.refuse_mutation()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  raise exception\n    '% is append-only: % is not permitted. Write a reversing entry instead.',\n    tg_table_name, tg_op\n    using errcode = 'restrict_violation';\nend;\n$$;\n\ncreate trigger journal_entry_immutable\n  before update or delete on journal_entry\n  for each row execute function app.refuse_mutation();\n\ncreate trigger journal_line_immutable\n  before update or delete on journal_line\n  for each row execute function app.refuse_mutation();\n\n-- ---------------------------------------------------------------------------\n-- Gap-free entry numbering. Postgres sequences leak numbers on rollback, which\n-- tax authorities do not accept; a locked counter row does not.\n-- ---------------------------------------------------------------------------\n\ncreate table number_series (\n  tenant_id   uuid not null references tenant(id) on delete cascade,\n  scope       text not null,          -- 'journal' or a document_type\n  year        integer not null,\n  next_value  bigint not null default 1,\n  prefix      text not null default '',\n  primary key (tenant_id, scope, year)\n);\n\ncreate or replace function app.next_number(\n  p_tenant uuid, p_scope text, p_year integer\n)\nreturns bigint\nlanguage plpgsql\nas $$\ndeclare\n  v_next bigint;\nbegin\n  insert into number_series (tenant_id, scope, year, next_value)\n  values (p_tenant, p_scope, p_year, 1)\n  on conflict (tenant_id, scope, year) do nothing;\n\n  -- FOR UPDATE serialises concurrent callers on this one row.\n  update number_series\n     set next_value = next_value + 1\n   where tenant_id = p_tenant and scope = p_scope and year = p_year\n  returning next_value - 1 into v_next;\n\n  return v_next;\nend;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Reversal. The only sanctioned way to undo a posted entry.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.reverse_entry(\n  p_entry_id uuid,\n  p_on       date default null,\n  p_memo     text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_src     journal_entry%rowtype;\n  v_new_id  uuid;\n  v_date    date;\n  v_period  uuid;\n  v_actor   uuid := app.current_user_id();\nbegin\n  select * into v_src from journal_entry where id = p_entry_id;\n  if not found then\n    raise exception 'journal entry % not found', p_entry_id;\n  end if;\n\n  if exists (select 1 from journal_entry where reverses_entry_id = p_entry_id) then\n    raise exception 'journal entry % has already been reversed', p_entry_id\n      using errcode = 'restrict_violation';\n  end if;\n\n  -- Reverse into today's period when the original period has since closed.\n  v_date   := coalesce(p_on, current_date);\n  v_period := app.open_period_for(v_src.tenant_id, v_date);\n\n  insert into journal_entry (\n    tenant_id, branch_id, fiscal_period_id, entry_no, entry_date,\n    memo_ar, source_doc_type, source_doc_id, reverses_entry_id, posted_by\n  ) values (\n    v_src.tenant_id, v_src.branch_id, v_period,\n    app.next_number(v_src.tenant_id, 'journal', extract(year from v_date)::int),\n    v_date,\n    coalesce(p_memo, 'عكس قيد رقم ' || v_src.entry_no),\n    v_src.source_doc_type, v_src.source_doc_id, v_src.id,\n    coalesce(v_actor, v_src.posted_by)\n  ) returning id into v_new_id;\n\n  -- Debits become credits and credits become debits.\n  insert into journal_line (\n    entry_id, tenant_id, line_no, account_id, party_id, branch_id,\n    debit, credit, currency, fx_rate, amount_foreign, memo\n  )\n  select\n    v_new_id, tenant_id, line_no, account_id, party_id, branch_id,\n    credit, debit, currency, fx_rate, amount_foreign, memo\n  from journal_line\n  where entry_id = p_entry_id;\n\n  return v_new_id;\nend;\n$$;\n"},{"name":"0005_parties_items_taxes.sql","sql":"-- =============================================================================\n-- 0005  Parties, catalogue and tax codes\n-- =============================================================================\n\ncreate table party (\n  id                  uuid primary key default gen_random_uuid(),\n  tenant_id           uuid not null references tenant(id) on delete cascade,\n  code                text not null,\n  name_ar             text not null,\n  name_en             text,\n\n  is_customer         boolean not null default true,\n  is_supplier         boolean not null default false,\n\n  -- ETA receiver identity. A business receiver must carry a tax registration\n  -- number; a person may carry a national id; neither is required for a\n  -- walk-in cash sale.\n  party_type          app.party_type not null default 'business',\n  tax_registration_no text,\n  national_id         text,\n\n  country             char(2) not null default 'EG',\n  governorate         text,\n  city                text,\n  street              text,\n  building_no         text,\n  phone               text,\n  email               text,\n\n  -- Control accounts. Receivable/payable postings land here.\n  receivable_account_id uuid references account(id),\n  payable_account_id    uuid references account(id),\n\n  credit_limit        numeric(18,5),\n  is_active           boolean not null default true,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n\n  unique (tenant_id, code),\n  constraint party_is_something check (is_customer or is_supplier),\n  constraint party_business_needs_trn\n    check (party_type <> 'business' or tax_registration_no is not null\n           or not is_customer)\n);\n\ncreate index party_tenant_idx on party (tenant_id) where is_active;\ncreate index party_name_idx   on party using gin (to_tsvector('simple', name_ar));\n\ncreate trigger party_touch before update on party\n  for each row execute function app.touch_updated_at();\n\n-- journal_line.party_id could not be constrained until party existed.\nalter table journal_line\n  add constraint journal_line_party_fk\n  foreign key (party_id) references party(id) on delete restrict;\n\n-- ---------------------------------------------------------------------------\n-- Units of measure and catalogue\n-- ---------------------------------------------------------------------------\n\ncreate table uom (\n  id          uuid primary key default gen_random_uuid(),\n  tenant_id   uuid not null references tenant(id) on delete cascade,\n  code        text not null,\n  name_ar     text not null,\n  eta_code    text,          -- ETA code table, e.g. 'EA', 'MTR', 'KGM'\n  unique (tenant_id, code)\n);\n\ncreate table item (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  code          text not null,\n  name_ar       text not null,\n  name_en       text,\n  uom_id        uuid references uom(id),\n\n  -- ETA requires a recognised code on every invoice line. Customers will not\n  -- have these on day one, which makes catalogue mapping an onboarding task,\n  -- not a data-entry one.\n  item_code_type text check (item_code_type in ('GS1', 'EGS')),\n  item_code      text,\n\n  default_tax_code_id uuid,   -- FK added below, once tax_code exists\n  sales_account_id    uuid references account(id),\n  purchase_account_id uuid references account(id),\n\n  is_active     boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n\n  unique (tenant_id, code),\n  constraint item_code_pairing\n    check ((item_code_type is null) = (item_code is null))\n);\n\ncreate index item_tenant_idx on item (tenant_id) where is_active;\n\ncreate trigger item_touch before update on item\n  for each row execute function app.touch_updated_at();\n\n-- ---------------------------------------------------------------------------\n-- Tax codes\n-- ---------------------------------------------------------------------------\n-- eta_tax_type / eta_subtype carry the authority's own code table values, so a\n-- line can be serialised into the ETA document schema without a lookup.\n--   T1 = value added tax        V009 = standard rate\n--   T2 = table tax, percentage  V003 = zero rated / export\n--   T3 = table tax, fixed       V007 = exempt\n--   T4 = withholding\n-- ---------------------------------------------------------------------------\n\ncreate table tax_code (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  code          text not null,\n  name_ar       text not null,\n  rate          numeric(7,4) not null,\n\n  eta_tax_type  text not null default 'T1',\n  eta_subtype   text,\n\n  -- Withholding is deducted by the buyer rather than added to the invoice, so\n  -- it posts with the opposite sign.\n  is_withholding boolean not null default false,\n\n  output_account_id uuid references account(id),  -- VAT collected on sales\n  input_account_id  uuid references account(id),  -- VAT paid on purchases\n\n  is_active     boolean not null default true,\n  unique (tenant_id, code),\n  constraint tax_code_rate_sane check (rate >= 0 and rate <= 100)\n);\n\nalter table item\n  add constraint item_default_tax_fk\n  foreign key (default_tax_code_id) references tax_code(id);\n"},{"name":"0006_documents.sql","sql":"-- =============================================================================\n-- 0006  Commercial documents and the review workflow\n-- =============================================================================\n-- A document is mutable while it is being prepared and frozen the moment it\n-- posts. That single rule satisfies two separate masters: an auditor, who\n-- needs history not to move, and the Tax Authority, for whom a cleared\n-- invoice is legally immutable and correctable only by a credit note.\n--\n-- The review workflow carried over from AZ Accounting maps exactly onto this:\n-- the reviewer's approval IS the moment of posting.\n-- =============================================================================\n\ncreate table document (\n  id               uuid primary key default gen_random_uuid(),\n  tenant_id        uuid not null references tenant(id) on delete cascade,\n  branch_id        uuid not null references branch(id),\n\n  doc_type         app.document_type not null,\n  doc_no           text not null,\n  status           app.document_status not null default 'draft',\n\n  party_id         uuid references party(id) on delete restrict,\n  issued_on        date not null default current_date,\n  due_on           date,\n\n  currency         char(3) not null default 'EGP',\n  fx_rate          numeric(18,8) not null default 1,\n\n  -- Denormalised totals, recomputed by trigger from the lines. Stored because\n  -- every list view needs them and recomputing on read does not scale.\n  subtotal         numeric(18,5) not null default 0,\n  discount_total   numeric(18,5) not null default 0,\n  tax_total        numeric(18,5) not null default 0,\n  total            numeric(18,5) not null default 0,\n\n  notes            text,\n\n  -- What this document corrects, for credit and debit notes.\n  corrects_doc_id  uuid references document(id),\n\n  -- Review workflow\n  created_by       uuid not null references app_user(id),\n  submitted_at     timestamptz,\n  reviewed_by      uuid references app_user(id),\n  reviewed_at      timestamptz,\n  rejection_reason text,\n\n  -- Ledger link, set at posting\n  journal_entry_id uuid references journal_entry(id),\n  posted_at        timestamptz,\n\n  -- Cancellation\n  cancelled_at     timestamptz,\n  cancelled_by     uuid references app_user(id),\n  cancel_reason    text,\n\n  -- ETA state. Populated by the submission worker in 0008.\n  eta_uuid         text,\n  eta_long_id      text,\n  eta_submission_uuid text,\n  eta_status       text not null default 'not_submitted'\n                     check (eta_status in ('not_submitted','queued','submitted',\n                                           'valid','invalid','rejected','cancelled')),\n  eta_submitted_at timestamptz,\n  eta_error        jsonb,\n\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  unique (tenant_id, doc_type, doc_no),\n  constraint document_fx_positive check (fx_rate > 0),\n  constraint document_posted_has_entry\n    check (status <> 'posted' or journal_entry_id is not null),\n  constraint document_rejected_has_reason\n    check (status <> 'rejected' or rejection_reason is not null),\n  constraint document_credit_note_corrects\n    check (doc_type not in ('sales_credit_note','sales_debit_note')\n           or corrects_doc_id is not null)\n);\n\ncreate index document_tenant_status_idx on document (tenant_id, status, issued_on desc);\ncreate index document_party_idx         on document (tenant_id, party_id);\ncreate index document_review_queue_idx  on document (tenant_id, submitted_at)\n  where status = 'pending_review';\ncreate index document_eta_pending_idx   on document (tenant_id, eta_status)\n  where eta_status in ('queued','submitted');\n\ncreate table document_line (\n  id            uuid primary key default gen_random_uuid(),\n  document_id   uuid not null references document(id) on delete cascade,\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  line_no       integer not null,\n\n  item_id       uuid references item(id) on delete restrict,\n  -- Copied from the item at entry time. The catalogue may change later; what\n  -- was invoiced must not.\n  description   text not null,\n  item_code_type text,\n  item_code     text,\n  uom_code      text,\n\n  quantity      numeric(18,5) not null,\n  unit_price    numeric(18,5) not null,\n  discount      numeric(18,5) not null default 0,\n\n  tax_code_id   uuid references tax_code(id),\n  tax_rate      numeric(7,4) not null default 0,\n  tax_amount    numeric(18,5) not null default 0,\n\n  line_total    numeric(18,5) not null default 0,\n\n  unique (document_id, line_no),\n  constraint document_line_qty_positive   check (quantity > 0),\n  constraint document_line_price_positive check (unit_price >= 0),\n  constraint document_line_discount_sane\n    check (discount >= 0 and discount <= quantity * unit_price)\n);\n\ncreate index document_line_doc_idx on document_line (document_id);\n\n-- ---------------------------------------------------------------------------\n-- Freeze rule\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.assert_document_mutable()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_editable constant app.document_status[] :=\n    array['draft','pending_review','rejected']::app.document_status[];\nbegin\n  if tg_op = 'DELETE' then\n    if old.status <> 'draft' then\n      raise exception\n        'document % is %; only a draft may be deleted', old.doc_no, old.status\n        using errcode = 'restrict_violation';\n    end if;\n    return old;\n  end if;\n\n  -- Leaving a frozen state is only ever allowed along sanctioned transitions.\n  if old.status = any(array['posted','cancelled']::app.document_status[]) then\n    if old.status = 'posted' and new.status = 'cancelled' then\n      null;  -- posted -> cancelled is the one permitted move\n    elsif old.status = new.status then\n      -- Same state: only ETA tracking fields may move, since clearance happens\n      -- asynchronously and long after posting.\n      if (new.id, new.doc_type, new.doc_no, new.party_id, new.issued_on,\n          new.subtotal, new.discount_total, new.tax_total, new.total,\n          new.journal_entry_id, new.branch_id, new.currency, new.fx_rate)\n         is distinct from\n         (old.id, old.doc_type, old.doc_no, old.party_id, old.issued_on,\n          old.subtotal, old.discount_total, old.tax_total, old.total,\n          old.journal_entry_id, old.branch_id, old.currency, old.fx_rate)\n      then\n        raise exception\n          'document % is % and cannot be edited. Issue a credit note instead.',\n          old.doc_no, old.status\n          using errcode = 'restrict_violation';\n      end if;\n    else\n      raise exception\n        'document % cannot move from % to %', old.doc_no, old.status, new.status\n        using errcode = 'restrict_violation';\n    end if;\n  end if;\n\n  return new;\nend;\n$$;\n\ncreate trigger document_freeze\n  before update or delete on document\n  for each row execute function app.assert_document_mutable();\n\n-- Lines follow their parent's state.\ncreate or replace function app.assert_line_mutable()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_status app.document_status;\n  v_doc    uuid := coalesce(new.document_id, old.document_id);\nbegin\n  select status into v_status from document where id = v_doc;\n\n  -- Parent already gone (ON DELETE CASCADE); nothing to guard.\n  if not found then\n    return coalesce(new, old);\n  end if;\n\n  if v_status not in ('draft','pending_review','rejected') then\n    raise exception\n      'cannot modify lines of a % document', v_status\n      using errcode = 'restrict_violation';\n  end if;\n\n  return coalesce(new, old);\nend;\n$$;\n\ncreate trigger document_line_freeze\n  before insert or update or delete on document_line\n  for each row execute function app.assert_line_mutable();\n\n-- ---------------------------------------------------------------------------\n-- Line arithmetic and document totals, computed in the database so that every\n-- client agrees on the numbers.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.compute_line_amounts()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_net numeric(18,5);\nbegin\n  if new.tax_code_id is not null and new.tax_rate = 0 then\n    select rate into new.tax_rate from tax_code where id = new.tax_code_id;\n  end if;\n\n  v_net := app.round5(new.quantity * new.unit_price - new.discount);\n  new.tax_amount := app.round5(v_net * new.tax_rate / 100);\n  new.line_total := app.round5(v_net + new.tax_amount);\n  return new;\nend;\n$$;\n\ncreate trigger document_line_amounts\n  before insert or update on document_line\n  for each row execute function app.compute_line_amounts();\n\ncreate or replace function app.recompute_document_totals()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_doc uuid := coalesce(new.document_id, old.document_id);\nbegin\n  update document d\n     set subtotal       = t.subtotal,\n         discount_total = t.discount_total,\n         tax_total      = t.tax_total,\n         total          = t.total\n    from (\n      select\n        app.round5(coalesce(sum(quantity * unit_price), 0))        as subtotal,\n        app.round5(coalesce(sum(discount), 0))                     as discount_total,\n        app.round5(coalesce(sum(tax_amount), 0))                   as tax_total,\n        app.round5(coalesce(sum(line_total), 0))                   as total\n      from document_line where document_id = v_doc\n    ) t\n   where d.id = v_doc;\n\n  return null;\nend;\n$$;\n\ncreate trigger document_line_totals\n  after insert or update or delete on document_line\n  for each row execute function app.recompute_document_totals();\n"},{"name":"0007_posting.sql","sql":"-- =============================================================================\n-- 0007  Posting: turning an approved document into ledger entries\n-- =============================================================================\n\n-- Which account each kind of posting lands in, per tenant.\ncreate table account_default (\n  tenant_id  uuid not null references tenant(id) on delete cascade,\n  purpose    text not null check (purpose in (\n               'receivable','payable','sales_revenue','purchases',\n               'vat_output','vat_input','cash','bank',\n               'discount_allowed','withholding_receivable','rounding')),\n  account_id uuid not null references account(id) on delete restrict,\n  primary key (tenant_id, purpose)\n);\n\ncreate or replace function app.default_account(p_tenant uuid, p_purpose text)\nreturns uuid\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_id uuid;\nbegin\n  select account_id into v_id\n  from account_default\n  where tenant_id = p_tenant and purpose = p_purpose;\n\n  if v_id is null then\n    raise exception 'no default account configured for \"%\"', p_purpose\n      using errcode = 'check_violation',\n            hint = 'Set it in account_default before posting.';\n  end if;\n  return v_id;\nend;\n$$;\n\n-- Settlement: which receipt paid which invoice, and how much of it.\ncreate table settlement (\n  id            uuid primary key default gen_random_uuid(),\n  tenant_id     uuid not null references tenant(id) on delete cascade,\n  receipt_id    uuid not null references document(id) on delete cascade,\n  invoice_id    uuid not null references document(id) on delete restrict,\n  amount        numeric(18,5) not null,\n  created_at    timestamptz not null default now(),\n\n  unique (receipt_id, invoice_id),\n  constraint settlement_amount_positive check (amount > 0)\n);\n\ncreate index settlement_invoice_idx on settlement (invoice_id);\n\n-- ---------------------------------------------------------------------------\n-- The posting rules, one branch per document type.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.post_document(p_doc_id uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_doc     document%rowtype;\n  v_entry   uuid;\n  v_period  uuid;\n  v_line_no integer := 0;\n  v_actor   uuid := app.current_user_id();\n  v_sign    integer;\n  r         record;\nbegin\n  select * into v_doc from document where id = p_doc_id for update;\n  if not found then\n    raise exception 'document % not found', p_doc_id;\n  end if;\n\n  if v_doc.status = 'posted' then\n    raise exception 'document % is already posted', v_doc.doc_no\n      using errcode = 'restrict_violation';\n  end if;\n\n  if not exists (select 1 from document_line where document_id = p_doc_id) then\n    raise exception 'document % has no lines', v_doc.doc_no\n      using errcode = 'check_violation';\n  end if;\n\n  v_period := app.open_period_for(v_doc.tenant_id, v_doc.issued_on);\n\n  insert into journal_entry (\n    tenant_id, branch_id, fiscal_period_id, entry_no, entry_date,\n    memo_ar, source_doc_type, source_doc_id, posted_by, approved_by\n  ) values (\n    v_doc.tenant_id, v_doc.branch_id, v_period,\n    app.next_number(v_doc.tenant_id, 'journal',\n                    extract(year from v_doc.issued_on)::int),\n    v_doc.issued_on,\n    v_doc.doc_type::text || ' ' || v_doc.doc_no,\n    v_doc.doc_type, v_doc.id,\n    coalesce(v_doc.created_by, v_actor),\n    coalesce(v_actor, v_doc.reviewed_by)\n  ) returning id into v_entry;\n\n  -- A credit note is a sales invoice with every sign flipped.\n  v_sign := case when v_doc.doc_type = 'sales_credit_note' then -1 else 1 end;\n\n  -- === Sales: invoice, credit note, debit note ==============================\n  if v_doc.doc_type in ('sales_invoice','sales_credit_note','sales_debit_note') then\n\n    -- Receivable takes the gross, on the customer's control account.\n    v_line_no := v_line_no + 1;\n    insert into journal_line (\n      entry_id, tenant_id, line_no, account_id, party_id, branch_id,\n      debit, credit, currency, fx_rate, memo\n    ) values (\n      v_entry, v_doc.tenant_id, v_line_no,\n      coalesce(\n        (select receivable_account_id from party where id = v_doc.party_id),\n        app.default_account(v_doc.tenant_id, 'receivable')),\n      v_doc.party_id, v_doc.branch_id,\n      case when v_sign > 0 then app.round5(v_doc.total) else 0 end,\n      case when v_sign < 0 then app.round5(v_doc.total) else 0 end,\n      v_doc.currency, v_doc.fx_rate, v_doc.doc_no\n    );\n\n    -- Revenue, grouped by the account each item maps to.\n    for r in\n      select\n        coalesce(i.sales_account_id,\n                 app.default_account(v_doc.tenant_id, 'sales_revenue')) as account_id,\n        app.round5(sum(dl.quantity * dl.unit_price - dl.discount))       as net\n      from document_line dl\n      left join item i on i.id = dl.item_id\n      where dl.document_id = p_doc_id\n      group by 1\n      having app.round5(sum(dl.quantity * dl.unit_price - dl.discount)) <> 0\n    loop\n      v_line_no := v_line_no + 1;\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, branch_id,\n        debit, credit, currency, fx_rate\n      ) values (\n        v_entry, v_doc.tenant_id, v_line_no, r.account_id, v_doc.branch_id,\n        case when v_sign < 0 then r.net else 0 end,\n        case when v_sign > 0 then r.net else 0 end,\n        v_doc.currency, v_doc.fx_rate\n      );\n    end loop;\n\n    -- Output VAT, grouped by tax code so each rate keeps its own account.\n    for r in\n      select\n        coalesce(tc.output_account_id,\n                 app.default_account(v_doc.tenant_id, 'vat_output')) as account_id,\n        app.round5(sum(dl.tax_amount))                               as tax\n      from document_line dl\n      left join tax_code tc on tc.id = dl.tax_code_id\n      where dl.document_id = p_doc_id\n      group by 1\n      having app.round5(sum(dl.tax_amount)) <> 0\n    loop\n      v_line_no := v_line_no + 1;\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, branch_id,\n        debit, credit, currency, fx_rate, memo\n      ) values (\n        v_entry, v_doc.tenant_id, v_line_no, r.account_id, v_doc.branch_id,\n        case when v_sign < 0 then r.tax else 0 end,\n        case when v_sign > 0 then r.tax else 0 end,\n        v_doc.currency, v_doc.fx_rate, 'ضريبة القيمة المضافة'\n      );\n    end loop;\n\n  -- === Purchases ============================================================\n  elsif v_doc.doc_type = 'purchase_invoice' then\n\n    for r in\n      select\n        coalesce(i.purchase_account_id,\n                 app.default_account(v_doc.tenant_id, 'purchases')) as account_id,\n        app.round5(sum(dl.quantity * dl.unit_price - dl.discount))  as net\n      from document_line dl\n      left join item i on i.id = dl.item_id\n      where dl.document_id = p_doc_id\n      group by 1\n      having app.round5(sum(dl.quantity * dl.unit_price - dl.discount)) <> 0\n    loop\n      v_line_no := v_line_no + 1;\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, branch_id,\n        debit, credit, currency, fx_rate\n      ) values (\n        v_entry, v_doc.tenant_id, v_line_no, r.account_id, v_doc.branch_id,\n        r.net, 0, v_doc.currency, v_doc.fx_rate\n      );\n    end loop;\n\n    if app.round5(v_doc.tax_total) <> 0 then\n      v_line_no := v_line_no + 1;\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, branch_id,\n        debit, credit, currency, fx_rate, memo\n      ) values (\n        v_entry, v_doc.tenant_id, v_line_no,\n        app.default_account(v_doc.tenant_id, 'vat_input'), v_doc.branch_id,\n        app.round5(v_doc.tax_total), 0, v_doc.currency, v_doc.fx_rate,\n        'ضريبة مدخلات'\n      );\n    end if;\n\n    v_line_no := v_line_no + 1;\n    insert into journal_line (\n      entry_id, tenant_id, line_no, account_id, party_id, branch_id,\n      debit, credit, currency, fx_rate, memo\n    ) values (\n      v_entry, v_doc.tenant_id, v_line_no,\n      coalesce((select payable_account_id from party where id = v_doc.party_id),\n               app.default_account(v_doc.tenant_id, 'payable')),\n      v_doc.party_id, v_doc.branch_id,\n      0, app.round5(v_doc.total), v_doc.currency, v_doc.fx_rate, v_doc.doc_no\n    );\n\n  -- === Cash in and out ======================================================\n  elsif v_doc.doc_type in ('receipt','payment') then\n    declare\n      v_cash  uuid := app.default_account(v_doc.tenant_id, 'cash');\n      v_ctrl  uuid;\n      v_in    boolean := (v_doc.doc_type = 'receipt');\n    begin\n      v_ctrl := case\n        when v_in then coalesce(\n               (select receivable_account_id from party where id = v_doc.party_id),\n               app.default_account(v_doc.tenant_id, 'receivable'))\n        else coalesce(\n               (select payable_account_id from party where id = v_doc.party_id),\n               app.default_account(v_doc.tenant_id, 'payable'))\n      end;\n\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, branch_id,\n        debit, credit, currency, fx_rate, memo\n      ) values (\n        v_entry, v_doc.tenant_id, 1, v_cash, v_doc.branch_id,\n        case when v_in then app.round5(v_doc.total) else 0 end,\n        case when v_in then 0 else app.round5(v_doc.total) end,\n        v_doc.currency, v_doc.fx_rate, v_doc.doc_no\n      );\n\n      insert into journal_line (\n        entry_id, tenant_id, line_no, account_id, party_id, branch_id,\n        debit, credit, currency, fx_rate, memo\n      ) values (\n        v_entry, v_doc.tenant_id, 2, v_ctrl, v_doc.party_id, v_doc.branch_id,\n        case when v_in then 0 else app.round5(v_doc.total) end,\n        case when v_in then app.round5(v_doc.total) else 0 end,\n        v_doc.currency, v_doc.fx_rate, v_doc.doc_no\n      );\n    end;\n\n  else\n    raise exception 'no posting rule for document type %', v_doc.doc_type;\n  end if;\n\n  update document\n     set status = 'posted',\n         journal_entry_id = v_entry,\n         posted_at = now(),\n         eta_status = case\n           when doc_type in ('sales_invoice','sales_credit_note','sales_debit_note')\n             then 'queued' else eta_status end\n   where id = p_doc_id;\n\n  return v_entry;\nend;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Workflow transitions. These are the only supported way to move a document.\n-- ---------------------------------------------------------------------------\n\ncreate or replace function app.submit_document(p_doc_id uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_status app.document_status;\nbegin\n  select status into v_status from document where id = p_doc_id for update;\n  if v_status not in ('draft','rejected') then\n    raise exception 'only a draft or rejected document may be submitted (is %)',\n      v_status using errcode = 'restrict_violation';\n  end if;\n\n  update document\n     set status = 'pending_review',\n         submitted_at = now(),\n         rejection_reason = null\n   where id = p_doc_id;\nend;\n$$;\n\ncreate or replace function app.approve_document(p_doc_id uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_doc    document%rowtype;\n  v_actor  uuid := app.current_user_id();\nbegin\n  select * into v_doc from document where id = p_doc_id for update;\n\n  if v_doc.status <> 'pending_review' then\n    raise exception 'document % is not awaiting review (is %)',\n      v_doc.doc_no, v_doc.status using errcode = 'restrict_violation';\n  end if;\n\n  -- Four eyes: whoever prepared it cannot be the one who approves it.\n  if v_actor is not null and v_actor = v_doc.created_by\n     and not app.has_role('owner') then\n    raise exception 'a document cannot be approved by the user who created it'\n      using errcode = 'restrict_violation',\n            hint = 'Another reviewer must approve this document.';\n  end if;\n\n  update document\n     set reviewed_by = v_actor, reviewed_at = now()\n   where id = p_doc_id;\n\n  return app.post_document(p_doc_id);\nend;\n$$;\n\ncreate or replace function app.reject_document(p_doc_id uuid, p_reason text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\nbegin\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'a rejection reason is required'\n      using errcode = 'check_violation';\n  end if;\n\n  update document\n     set status = 'rejected',\n         rejection_reason = p_reason,\n         reviewed_by = app.current_user_id(),\n         reviewed_at = now()\n   where id = p_doc_id and status = 'pending_review';\n\n  if not found then\n    raise exception 'document % is not awaiting review', p_doc_id\n      using errcode = 'restrict_violation';\n  end if;\nend;\n$$;\n\ncreate or replace function app.cancel_document(p_doc_id uuid, p_reason text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_doc      document%rowtype;\n  v_reversal uuid;\nbegin\n  select * into v_doc from document where id = p_doc_id for update;\n\n  if v_doc.status <> 'posted' then\n    raise exception 'only a posted document may be cancelled (is %)', v_doc.status\n      using errcode = 'restrict_violation';\n  end if;\n\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'a cancellation reason is required'\n      using errcode = 'check_violation';\n  end if;\n\n  -- Cleared by the authority: cancellation is no longer ours to make.\n  if v_doc.eta_status = 'valid' then\n    raise exception\n      'document % has been cleared by the Tax Authority and cannot be cancelled',\n      v_doc.doc_no\n      using errcode = 'restrict_violation',\n            hint = 'Issue a credit note (إشعار دائن) instead.';\n  end if;\n\n  v_reversal := app.reverse_entry(\n    v_doc.journal_entry_id, current_date,\n    'إلغاء ' || v_doc.doc_no || ' - ' || p_reason);\n\n  update document\n     set status = 'cancelled',\n         cancelled_at = now(),\n         cancelled_by = app.current_user_id(),\n         cancel_reason = p_reason\n   where id = p_doc_id;\n\n  return v_reversal;\nend;\n$$;\n"},{"name":"0008_eta_queue.sql","sql":"-- =============================================================================\n-- 0008  ETA submission queue and audit log\n-- =============================================================================\n-- Issuing an invoice and clearing it with the Tax Authority are deliberately\n-- decoupled. A sale completes on local state alone; clearance catches up when\n-- the network allows. This is not an optimisation -- Egyptian connectivity is\n-- unreliable, the authority permits a submission window, and a shop cannot\n-- stop selling because a line is down.\n-- =============================================================================\n\ncreate table eta_submission (\n  id              uuid primary key default gen_random_uuid(),\n  tenant_id       uuid not null references tenant(id) on delete cascade,\n  document_id     uuid not null references document(id) on delete cascade,\n\n  state           text not null default 'pending'\n                    check (state in ('pending','in_flight','succeeded','failed')),\n\n  attempts        integer not null default 0,\n  max_attempts    integer not null default 12,\n  next_attempt_at timestamptz not null default now(),\n\n  -- The canonical serialisation and its hash, retained exactly as signed.\n  -- Regenerating it later could produce different bytes, which would make the\n  -- signature unverifiable.\n  canonical_json  text,\n  payload_hash    text,\n  signed_payload  text,\n\n  -- Worker lease, so two workers never submit the same document twice.\n  locked_at       timestamptz,\n  locked_by       text,\n\n  last_error      jsonb,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  unique (document_id)\n);\n\ncreate index eta_submission_ready_idx\n  on eta_submission (next_attempt_at)\n  where state = 'pending';\n\ncreate trigger eta_submission_touch before update on eta_submission\n  for each row execute function app.touch_updated_at();\n\ncreate table eta_submission_attempt (\n  id             uuid primary key default gen_random_uuid(),\n  submission_id  uuid not null references eta_submission(id) on delete cascade,\n  attempt_no     integer not null,\n  started_at     timestamptz not null default now(),\n  finished_at    timestamptz,\n  http_status    integer,\n  response       jsonb,\n  error          text\n);\n\ncreate index eta_attempt_submission_idx on eta_submission_attempt (submission_id);\n\n-- Every posted sales document enters the queue automatically.\ncreate or replace function app.enqueue_for_eta()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if new.status = 'posted'\n     and new.doc_type in ('sales_invoice','sales_credit_note','sales_debit_note')\n     and (old.status is distinct from 'posted')\n  then\n    insert into eta_submission (tenant_id, document_id)\n    values (new.tenant_id, new.id)\n    on conflict (document_id) do nothing;\n  end if;\n  return null;\nend;\n$$;\n\ncreate trigger document_enqueue_eta\n  after update on document\n  for each row execute function app.enqueue_for_eta();\n\n-- ---------------------------------------------------------------------------\n-- Worker interface\n-- ---------------------------------------------------------------------------\n\n-- Claims up to p_limit due submissions and leases them. SKIP LOCKED lets\n-- several workers run concurrently without contending on the same rows.\ncreate or replace function app.claim_eta_submissions(\n  p_worker text, p_limit integer default 10\n)\nreturns setof eta_submission\nlanguage plpgsql\nas $$\nbegin\n  return query\n  update eta_submission s\n     set state = 'in_flight',\n         attempts = s.attempts + 1,\n         locked_at = now(),\n         locked_by = p_worker\n   where s.id in (\n     select id from eta_submission\n      where state = 'pending'\n        and next_attempt_at <= now()\n      order by next_attempt_at\n      limit p_limit\n      for update skip locked\n   )\n  returning s.*;\nend;\n$$;\n\ncreate or replace function app.complete_eta_submission(\n  p_submission_id uuid,\n  p_uuid          text,\n  p_long_id       text,\n  p_response      jsonb default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_doc uuid;\nbegin\n  update eta_submission\n     set state = 'succeeded', locked_at = null, locked_by = null,\n         last_error = null\n   where id = p_submission_id\n  returning document_id into v_doc;\n\n  if v_doc is null then\n    raise exception 'submission % not found', p_submission_id;\n  end if;\n\n  insert into eta_submission_attempt\n    (submission_id, attempt_no, finished_at, http_status, response)\n  select id, attempts, now(), 200, p_response\n  from eta_submission where id = p_submission_id;\n\n  -- Permitted on a posted document: only the ETA tracking fields move.\n  update document\n     set eta_uuid = p_uuid,\n         eta_long_id = p_long_id,\n         eta_status = 'valid',\n         eta_submitted_at = now(),\n         eta_error = null\n   where id = v_doc;\nend;\n$$;\n\n-- Records a failure and schedules the retry with exponential backoff,\n-- capped at one hour. A permanent rejection stops retrying immediately.\ncreate or replace function app.fail_eta_submission(\n  p_submission_id uuid,\n  p_error         jsonb,\n  p_permanent     boolean default false\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_sub eta_submission%rowtype;\n  v_backoff interval;\nbegin\n  select * into v_sub from eta_submission where id = p_submission_id for update;\n  if not found then\n    raise exception 'submission % not found', p_submission_id;\n  end if;\n\n  insert into eta_submission_attempt\n    (submission_id, attempt_no, finished_at, response, error)\n  values (p_submission_id, v_sub.attempts, now(), p_error, p_error ->> 'message');\n\n  if p_permanent or v_sub.attempts >= v_sub.max_attempts then\n    update eta_submission\n       set state = 'failed', last_error = p_error,\n           locked_at = null, locked_by = null\n     where id = p_submission_id;\n\n    update document\n       set eta_status = case when p_permanent then 'rejected' else 'invalid' end,\n           eta_error = p_error\n     where id = v_sub.document_id;\n  else\n    v_backoff := least(\n      make_interval(secs => power(2, v_sub.attempts)::int * 30),\n      interval '1 hour');\n\n    update eta_submission\n       set state = 'pending',\n           next_attempt_at = now() + v_backoff,\n           last_error = p_error,\n           locked_at = null, locked_by = null\n     where id = p_submission_id;\n  end if;\nend;\n$$;\n\n-- Releases leases held by a worker that died mid-flight.\ncreate or replace function app.reclaim_stale_eta_leases(\n  p_older_than interval default interval '10 minutes'\n)\nreturns integer\nlanguage plpgsql\nas $$\ndeclare\n  v_count integer;\nbegin\n  update eta_submission\n     set state = 'pending', locked_at = null, locked_by = null\n   where state = 'in_flight'\n     and locked_at < now() - p_older_than;\n  get diagnostics v_count = row_count;\n  return v_count;\nend;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Audit log\n-- ---------------------------------------------------------------------------\n\ncreate table audit_log (\n  id          bigserial primary key,\n  tenant_id   uuid,\n  actor_id    uuid,\n  action      text not null,\n  table_name  text not null,\n  row_id      uuid,\n  before      jsonb,\n  after       jsonb,\n  at          timestamptz not null default now()\n);\n\ncreate index audit_log_tenant_idx on audit_log (tenant_id, at desc);\ncreate index audit_log_row_idx    on audit_log (table_name, row_id);\n\ncreate or replace function app.write_audit()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_row jsonb := to_jsonb(coalesce(new, old));\nbegin\n  insert into audit_log (tenant_id, actor_id, action, table_name, row_id, before, after)\n  values (\n    (v_row ->> 'tenant_id')::uuid,\n    app.current_user_id(),\n    tg_op,\n    tg_table_name,\n    (v_row ->> 'id')::uuid,\n    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,\n    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end\n  );\n  return null;\nend;\n$$;\n\ncreate trigger document_audit\n  after insert or update or delete on document\n  for each row execute function app.write_audit();\n\ncreate trigger journal_entry_audit\n  after insert on journal_entry\n  for each row execute function app.write_audit();\n\ncreate trigger app_user_audit\n  after insert or update or delete on app_user\n  for each row execute function app.write_audit();\n"},{"name":"0009_rls.sql","sql":"-- =============================================================================\n-- 0009  Row level security\n-- =============================================================================\n-- Two things are enforced here:\n--   1. Tenant isolation. No row ever crosses a tenant boundary.\n--   2. The six-role permission model carried over from AZ Accounting.\n--\n-- Policy predicates wrap helper calls in a scalar subquery -- (select app.x())\n-- -- so the planner evaluates them once per statement rather than once per row.\n-- =============================================================================\n\nalter table tenant           enable row level security;\nalter table branch           enable row level security;\nalter table app_user         enable row level security;\nalter table account          enable row level security;\nalter table account_default  enable row level security;\nalter table fiscal_year      enable row level security;\nalter table fiscal_period    enable row level security;\nalter table journal_entry    enable row level security;\nalter table journal_line     enable row level security;\nalter table number_series    enable row level security;\nalter table party            enable row level security;\nalter table uom              enable row level security;\nalter table item             enable row level security;\nalter table tax_code         enable row level security;\nalter table document         enable row level security;\nalter table document_line    enable row level security;\nalter table settlement       enable row level security;\nalter table eta_submission   enable row level security;\nalter table eta_submission_attempt enable row level security;\nalter table audit_log        enable row level security;\n\n-- ---------------------------------------------------------------------------\n-- Tenant, branches, users\n-- ---------------------------------------------------------------------------\n\ncreate policy tenant_read on tenant for select\n  using (id = (select app.current_tenant_id()));\n\ncreate policy tenant_write on tenant for update\n  using (id = (select app.current_tenant_id()) and (select app.has_role('owner')))\n  with check (id = (select app.current_tenant_id())\n              and (select app.has_role('owner')));\n\ncreate policy branch_read on branch for select\n  using (tenant_id = (select app.current_tenant_id()));\n\ncreate policy branch_write on branch for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')));\n\n-- Everyone can see who their colleagues are; only owners and managers\n-- create users or approve their logins.\ncreate policy app_user_read on app_user for select\n  using (tenant_id = (select app.current_tenant_id()));\n\ncreate policy app_user_write on app_user for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')));\n\n-- ---------------------------------------------------------------------------\n-- Reference data: readable by all staff, maintained by owner/manager\n-- ---------------------------------------------------------------------------\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['account','uom','item','tax_code','account_default'] loop\n    execute format($f$\n      create policy %1$s_read on %1$s for select\n        using (tenant_id = (select app.current_tenant_id()));\n      create policy %1$s_write on %1$s for all\n        using (tenant_id = (select app.current_tenant_id())\n               and (select app.has_role('owner','manager')))\n        with check (tenant_id = (select app.current_tenant_id())\n               and (select app.has_role('owner','manager')));\n    $f$, t);\n  end loop;\nend $$;\n\ncreate policy fiscal_year_read on fiscal_year for select\n  using (tenant_id = (select app.current_tenant_id()));\ncreate policy fiscal_year_write on fiscal_year for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')));\n\ncreate policy fiscal_period_read on fiscal_period for select\n  using (tenant_id = (select app.current_tenant_id()));\ncreate policy fiscal_period_write on fiscal_period for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager')));\n\ncreate policy number_series_rw on number_series for all\n  using (tenant_id = (select app.current_tenant_id()))\n  with check (tenant_id = (select app.current_tenant_id()));\n\n-- ---------------------------------------------------------------------------\n-- Parties\n-- ---------------------------------------------------------------------------\n-- invoice_viewer is deliberately excluded: that role sees documents only.\n\ncreate policy party_read on party for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','supervisor',\n                                  'data_entry','reviewer','viewer')));\n\ncreate policy party_write on party for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','data_entry')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','data_entry')));\n\n-- ---------------------------------------------------------------------------\n-- The ledger is read-only to everyone. It is written only through\n-- SECURITY DEFINER functions, which is the whole point of the design.\n-- ---------------------------------------------------------------------------\n\ncreate policy journal_entry_read on journal_entry for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.can_read_ledger()));\n\ncreate policy journal_line_read on journal_line for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.can_read_ledger()));\n\n-- ---------------------------------------------------------------------------\n-- Documents\n-- ---------------------------------------------------------------------------\n\ncreate policy document_read on document for select\n  using (tenant_id = (select app.current_tenant_id()));\n\n-- Data entry may create drafts and edit only their own unposted work.\ncreate policy document_insert on document for insert\n  with check (\n    tenant_id = (select app.current_tenant_id())\n    and (select app.has_role('owner','manager','data_entry'))\n    and status = 'draft'\n  );\n\ncreate policy document_update on document for update\n  using (\n    tenant_id = (select app.current_tenant_id())\n    and status in ('draft','pending_review','rejected')\n    and (\n      (select app.has_role('owner','manager','reviewer'))\n      or ((select app.has_role('data_entry')) and created_by = (select app.current_user_id()))\n    )\n  )\n  with check (\n    tenant_id = (select app.current_tenant_id())\n    -- A client may never move a document into the ledger by hand; posting\n    -- happens only through app.approve_document().\n    and status in ('draft','pending_review','rejected')\n  );\n\ncreate policy document_delete on document for delete\n  using (\n    tenant_id = (select app.current_tenant_id())\n    and status = 'draft'\n    and (\n      (select app.has_role('owner','manager'))\n      or ((select app.has_role('data_entry')) and created_by = (select app.current_user_id()))\n    )\n  );\n\ncreate policy document_line_read on document_line for select\n  using (tenant_id = (select app.current_tenant_id()));\n\ncreate policy document_line_write on document_line for all\n  using (\n    tenant_id = (select app.current_tenant_id())\n    and exists (\n      select 1 from document d\n      where d.id = document_line.document_id\n        and d.status in ('draft','pending_review','rejected')\n        and (\n          (select app.has_role('owner','manager','reviewer'))\n          or ((select app.has_role('data_entry')) and d.created_by = (select app.current_user_id()))\n        )\n    )\n  )\n  with check (\n    tenant_id = (select app.current_tenant_id())\n    and exists (\n      select 1 from document d\n      where d.id = document_line.document_id\n        and d.status in ('draft','pending_review','rejected')\n        and (\n          (select app.has_role('owner','manager','reviewer'))\n          or ((select app.has_role('data_entry')) and d.created_by = (select app.current_user_id()))\n        )\n    )\n  );\n\ncreate policy settlement_read on settlement for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.can_read_ledger()));\n\ncreate policy settlement_write on settlement for all\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','data_entry')))\n  with check (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','data_entry')));\n\n-- ---------------------------------------------------------------------------\n-- ETA queue and audit: visible to management, written by the worker\n-- ---------------------------------------------------------------------------\n\ncreate policy eta_submission_read on eta_submission for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','supervisor','reviewer')));\n\ncreate policy eta_attempt_read on eta_submission_attempt for select\n  using (exists (\n    select 1 from eta_submission s\n    where s.id = eta_submission_attempt.submission_id\n      and s.tenant_id = (select app.current_tenant_id())\n      and (select app.has_role('owner','manager','supervisor','reviewer'))\n  ));\n\ncreate policy audit_log_read on audit_log for select\n  using (tenant_id = (select app.current_tenant_id())\n         and (select app.has_role('owner','manager','supervisor')));\n\n-- ---------------------------------------------------------------------------\n-- tenant.eta_client_secret must never leave the server. No policy grants\n-- column access, so expose tenants to clients through this view instead.\n-- ---------------------------------------------------------------------------\n\ncreate view tenant_public\nwith (security_invoker = true)\nas\n  select id, name, legal_name_ar, legal_name_en, tax_registration_no,\n         commercial_reg_no, eta_environment, base_currency, vat_registered,\n         created_at, updated_at\n  from tenant;\n"},{"name":"0010_reporting.sql","sql":"-- =============================================================================\n-- 0010  Reporting views\n-- =============================================================================\n-- security_invoker means these read through the caller's RLS policies rather\n-- than the view owner's, so a viewer cannot use a report to see another\n-- tenant's numbers.\n-- =============================================================================\n\n-- Every posted movement, flattened. The base for most reports.\ncreate view ledger_movement\nwith (security_invoker = true)\nas\nselect\n  jl.id            as line_id,\n  je.tenant_id,\n  je.branch_id,\n  je.id            as entry_id,\n  je.entry_no,\n  je.entry_date,\n  je.fiscal_period_id,\n  je.source_doc_type,\n  je.source_doc_id,\n  je.reverses_entry_id is not null as is_reversal,\n  a.id             as account_id,\n  a.code           as account_code,\n  a.name_ar        as account_name,\n  a.type           as account_type,\n  jl.party_id,\n  p.name_ar        as party_name,\n  jl.debit,\n  jl.credit,\n  jl.debit - jl.credit as signed_amount,\n  jl.currency,\n  jl.memo\nfrom journal_line jl\njoin journal_entry je on je.id = jl.entry_id\njoin account a        on a.id = jl.account_id\nleft join party p     on p.id = jl.party_id;\n\n-- Trial balance. Should always net to zero per tenant; if it does not, the\n-- balance constraint in 0004 has been bypassed somehow.\ncreate view trial_balance\nwith (security_invoker = true)\nas\nselect\n  a.tenant_id,\n  a.id      as account_id,\n  a.code    as account_code,\n  a.name_ar as account_name,\n  a.type    as account_type,\n  coalesce(sum(jl.debit), 0)  as total_debit,\n  coalesce(sum(jl.credit), 0) as total_credit,\n  case a.normal_balance\n    when 'debit'  then coalesce(sum(jl.debit - jl.credit), 0)\n    else               coalesce(sum(jl.credit - jl.debit), 0)\n  end as balance\nfrom account a\nleft join journal_line jl on jl.account_id = a.id\nwhere a.is_postable\ngroup by a.tenant_id, a.id, a.code, a.name_ar, a.type, a.normal_balance;\n\n-- Customer / supplier statement -- كشف حساب.\n-- This is the report AZ Accounting was built around, now derived from the\n-- ledger rather than stored separately.\ncreate view party_statement\nwith (security_invoker = true)\nas\nselect\n  jl.tenant_id,\n  jl.party_id,\n  je.entry_date,\n  je.entry_no,\n  je.source_doc_type,\n  d.doc_no,\n  jl.memo,\n  jl.debit,\n  jl.credit,\n  sum(jl.debit - jl.credit) over (\n    partition by jl.tenant_id, jl.party_id\n    order by je.entry_date, je.entry_no, jl.line_no\n    rows between unbounded preceding and current row\n  ) as running_balance\nfrom journal_line jl\njoin journal_entry je on je.id = jl.entry_id\nleft join document d  on d.id = je.source_doc_id\nwhere jl.party_id is not null;\n\ncreate view party_balance\nwith (security_invoker = true)\nas\nselect\n  p.tenant_id,\n  p.id   as party_id,\n  p.code,\n  p.name_ar,\n  p.is_customer,\n  p.is_supplier,\n  coalesce(sum(jl.debit - jl.credit), 0) as balance,\n  p.credit_limit,\n  p.credit_limit is not null\n    and coalesce(sum(jl.debit - jl.credit), 0) > p.credit_limit as over_limit\nfrom party p\nleft join journal_line jl on jl.party_id = p.id\ngroup by p.tenant_id, p.id, p.code, p.name_ar, p.is_customer,\n         p.is_supplier, p.credit_limit;\n\n-- Receivables ageing -- أعمار الديون.\ncreate view receivable_ageing\nwith (security_invoker = true)\nas\nwith open_invoices as (\n  select\n    d.tenant_id, d.party_id, d.id, d.doc_no, d.issued_on,\n    coalesce(d.due_on, d.issued_on) as due_on,\n    d.total - coalesce((\n      select sum(s.amount) from settlement s where s.invoice_id = d.id\n    ), 0) as outstanding\n  from document d\n  where d.doc_type = 'sales_invoice'\n    and d.status = 'posted'\n)\nselect\n  oi.tenant_id,\n  oi.party_id,\n  p.name_ar as party_name,\n  oi.id as document_id,\n  oi.doc_no,\n  oi.issued_on,\n  oi.due_on,\n  oi.outstanding,\n  (current_date - oi.due_on) as days_overdue,\n  case\n    when current_date <= oi.due_on                 then 'current'\n    when current_date - oi.due_on <= 30            then '1-30'\n    when current_date - oi.due_on <= 60            then '31-60'\n    when current_date - oi.due_on <= 90            then '61-90'\n    else                                                '90+'\n  end as bucket\nfrom open_invoices oi\njoin party p on p.id = oi.party_id\nwhere oi.outstanding > 0;\n\n-- What the reviewer sees when they open their queue.\ncreate view review_queue\nwith (security_invoker = true)\nas\nselect\n  d.tenant_id, d.id, d.doc_type, d.doc_no, d.issued_on, d.total, d.currency,\n  d.submitted_at,\n  p.name_ar  as party_name,\n  u.full_name as created_by_name,\n  (select count(*) from document_line dl where dl.document_id = d.id) as line_count\nfrom document d\nleft join party p    on p.id = d.party_id\njoin app_user u      on u.id = d.created_by\nwhere d.status = 'pending_review';\n\n-- Operational health of the ETA queue.\ncreate view eta_queue_status\nwith (security_invoker = true)\nas\nselect\n  s.tenant_id,\n  s.state,\n  count(*)                                          as documents,\n  min(s.next_attempt_at) filter (where s.state = 'pending') as next_due,\n  sum(d.total)                                      as total_value,\n  max(s.attempts)                                   as worst_attempts\nfrom eta_submission s\njoin document d on d.id = s.document_id\ngroup by s.tenant_id, s.state;\n"},{"name":"0011_provisioning.sql","sql":"-- =============================================================================\n-- 0011  Tenant provisioning\n-- =============================================================================\n-- Creates a working company in one call: chart of accounts, tax codes, units,\n-- default account mappings, a branch, and a fiscal year with twelve periods.\n-- A new customer should never face an empty chart of accounts.\n-- =============================================================================\n\ncreate or replace function app.provision_tenant(\n  p_name            text,\n  p_legal_name_ar   text,\n  p_owner_user_id   uuid,\n  p_owner_username  text default 'manager',\n  p_owner_full_name text default 'المدير',\n  p_year            integer default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, app\nas $$\ndeclare\n  v_tenant uuid;\n  v_branch uuid;\n  v_year   integer := coalesce(p_year, extract(year from current_date)::int);\n  v_fy     uuid;\n  m        integer;\n  rec      record;\n  v_acc    uuid;\n\n  -- code, name_ar, name_en, type, normal_balance, parent_code, postable\n  accounts constant text[][] := array[\n    -- === الأصول =============================================================\n    ['1000','الأصول','Assets','asset','debit','','f'],\n    ['1100','الأصول المتداولة','Current Assets','asset','debit','1000','f'],\n    ['1110','الصندوق','Cash on Hand','asset','debit','1100','t'],\n    ['1120','البنك','Bank','asset','debit','1100','t'],\n    ['1130','العملاء','Accounts Receivable','asset','debit','1100','t'],\n    ['1140','أوراق القبض','Notes Receivable','asset','debit','1100','t'],\n    ['1150','المخزون','Inventory','asset','debit','1100','t'],\n    ['1160','ضريبة القيمة المضافة - مدخلات','Input VAT','asset','debit','1100','t'],\n    ['1170','ضريبة مستقطعة تحت الحساب','Withholding Tax Receivable','asset','debit','1100','t'],\n    ['1180','مصروفات مدفوعة مقدماً','Prepaid Expenses','asset','debit','1100','t'],\n    ['1200','الأصول الثابتة','Fixed Assets','asset','debit','1000','f'],\n    ['1210','أثاث ومعدات','Furniture and Equipment','asset','debit','1200','t'],\n    ['1220','مجمع الإهلاك','Accumulated Depreciation','asset','credit','1200','t'],\n\n    -- === الخصوم =============================================================\n    ['2000','الخصوم','Liabilities','liability','credit','','f'],\n    ['2100','الخصوم المتداولة','Current Liabilities','liability','credit','2000','f'],\n    ['2110','الموردون','Accounts Payable','liability','credit','2100','t'],\n    ['2120','أوراق الدفع','Notes Payable','liability','credit','2100','t'],\n    ['2130','ضريبة القيمة المضافة - مخرجات','Output VAT','liability','credit','2100','t'],\n    ['2140','التأمينات الاجتماعية','Social Insurance Payable','liability','credit','2100','t'],\n    ['2150','ضريبة كسب العمل','Payroll Tax Payable','liability','credit','2100','t'],\n    ['2160','مصروفات مستحقة','Accrued Expenses','liability','credit','2100','t'],\n\n    -- === حقوق الملكية ========================================================\n    ['3000','حقوق الملكية','Equity','equity','credit','','f'],\n    ['3100','رأس المال','Capital','equity','credit','3000','t'],\n    ['3200','الأرباح المحتجزة','Retained Earnings','equity','credit','3000','t'],\n    ['3300','المسحوبات','Drawings','equity','debit','3000','t'],\n\n    -- === الإيرادات ==========================================================\n    ['4000','الإيرادات','Revenue','revenue','credit','','f'],\n    ['4100','إيرادات المبيعات','Sales Revenue','revenue','credit','4000','t'],\n    ['4200','مردودات المبيعات','Sales Returns','revenue','debit','4000','t'],\n    ['4300','خصم مسموح به','Discounts Allowed','revenue','debit','4000','t'],\n    ['4900','إيرادات أخرى','Other Income','revenue','credit','4000','t'],\n\n    -- === المصروفات ==========================================================\n    ['5000','المصروفات','Expenses','expense','debit','','f'],\n    ['5100','تكلفة المبيعات','Cost of Sales','expense','debit','5000','t'],\n    ['5200','المشتريات','Purchases','expense','debit','5000','t'],\n    ['5300','الأجور والمرتبات','Salaries and Wages','expense','debit','5000','t'],\n    ['5400','الإيجار','Rent','expense','debit','5000','t'],\n    ['5500','الكهرباء والمياه','Utilities','expense','debit','5000','t'],\n    ['5600','مصروفات نقل وشحن','Freight and Transport','expense','debit','5000','t'],\n    ['5700','مصروفات بنكية','Bank Charges','expense','debit','5000','t'],\n    ['5800','الإهلاك','Depreciation','expense','debit','5000','t'],\n    ['5900','مصروفات متنوعة','Miscellaneous','expense','debit','5000','t'],\n    ['5950','فروق عملة','FX Differences','expense','debit','5000','t']\n  ];\nbegin\n  insert into tenant (name, legal_name_ar, vat_registered)\n  values (p_name, p_legal_name_ar, true)\n  returning id into v_tenant;\n\n  insert into branch (tenant_id, code, name, governorate, city)\n  values (v_tenant, 'MAIN', 'الفرع الرئيسي', 'القاهرة', 'القاهرة')\n  returning id into v_branch;\n\n  insert into app_user (id, tenant_id, branch_id, username, full_name,\n                        role, is_approved, approved_at)\n  values (p_owner_user_id, v_tenant, v_branch, p_owner_username,\n          p_owner_full_name, 'owner', true, now());\n\n  -- Chart of accounts, parents before children.\n  for i in 1 .. array_length(accounts, 1) loop\n    insert into account (tenant_id, parent_id, code, name_ar, name_en,\n                         type, normal_balance, is_postable)\n    values (\n      v_tenant,\n      case when accounts[i][6] <> '' then\n        (select id from account\n          where tenant_id = v_tenant and code = accounts[i][6])\n      end,\n      accounts[i][1], accounts[i][2], accounts[i][3],\n      accounts[i][4]::app.account_type,\n      accounts[i][5]::app.normal_balance,\n      accounts[i][7]::boolean\n    );\n  end loop;\n\n  -- Egyptian VAT codes. eta_subtype values are the authority's own code table.\n  insert into tax_code (tenant_id, code, name_ar, rate, eta_tax_type,\n                        eta_subtype, output_account_id, input_account_id)\n  select v_tenant, x.code, x.name_ar, x.rate, 'T1', x.subtype,\n         (select id from account where tenant_id = v_tenant and code = '2130'),\n         (select id from account where tenant_id = v_tenant and code = '1160')\n  from (values\n    ('VAT14', 'ضريبة القيمة المضافة 14%', 14.0, 'V009'),\n    ('VAT10', 'ضريبة الجدول 10%',          10.0, 'V009'),\n    ('VAT5',  'ضريبة الجدول 5%',            5.0, 'V009'),\n    ('VAT0',  'معدل صفري / تصدير',          0.0, 'V003'),\n    ('EXEMPT','معفاة',                      0.0, 'V007')\n  ) as x(code, name_ar, rate, subtype);\n\n  -- Withholding is deducted by the buyer, not charged on the invoice.\n  insert into tax_code (tenant_id, code, name_ar, rate, eta_tax_type,\n                        eta_subtype, is_withholding, input_account_id)\n  select v_tenant, x.code, x.name_ar, x.rate, 'T4', x.subtype, true,\n         (select id from account where tenant_id = v_tenant and code = '1170')\n  from (values\n    ('WHT1', 'خصم وتحصيل 1%', 1.0, 'W001'),\n    ('WHT3', 'خصم وتحصيل 3%', 3.0, 'W003'),\n    ('WHT5', 'خصم وتحصيل 5%', 5.0, 'W005')\n  ) as x(code, name_ar, rate, subtype);\n\n  insert into uom (tenant_id, code, name_ar, eta_code)\n  values\n    (v_tenant, 'EA',  'قطعة',  'EA'),\n    (v_tenant, 'MTR', 'متر',   'MTR'),\n    (v_tenant, 'KGM', 'كيلو',  'KGM'),\n    (v_tenant, 'LTR', 'لتر',   'LTR'),\n    (v_tenant, 'BOX', 'كرتونة','BX'),\n    (v_tenant, 'TON', 'طن',    'TNE');\n\n  -- Wire the posting rules to real accounts.\n  insert into account_default (tenant_id, purpose, account_id)\n  select v_tenant, x.purpose,\n         (select id from account where tenant_id = v_tenant and code = x.code)\n  from (values\n    ('receivable','1130'), ('payable','2110'),\n    ('sales_revenue','4100'), ('purchases','5200'),\n    ('vat_output','2130'), ('vat_input','1160'),\n    ('cash','1110'), ('bank','1120'),\n    ('discount_allowed','4300'),\n    ('withholding_receivable','1170'),\n    ('rounding','5900')\n  ) as x(purpose, code);\n\n  -- Fiscal year with twelve calendar months.\n  insert into fiscal_year (tenant_id, name, starts_on, ends_on)\n  values (v_tenant, v_year::text,\n          make_date(v_year, 1, 1), make_date(v_year, 12, 31))\n  returning id into v_fy;\n\n  for m in 1 .. 12 loop\n    insert into fiscal_period (tenant_id, fiscal_year_id, name, starts_on, ends_on)\n    values (\n      v_tenant, v_fy,\n      to_char(make_date(v_year, m, 1), 'YYYY-MM'),\n      make_date(v_year, m, 1),\n      (make_date(v_year, m, 1) + interval '1 month - 1 day')::date\n    );\n  end loop;\n\n  return v_tenant;\nend;\n$$;\n\n-- Allocates the next document number for a type, formatted with its year.\ncreate or replace function app.next_document_no(\n  p_tenant uuid, p_type app.document_type, p_on date default current_date\n)\nreturns text\nlanguage plpgsql\nas $$\ndeclare\n  v_year   integer := extract(year from p_on)::int;\n  v_prefix text := case p_type\n    when 'sales_invoice'     then 'INV'\n    when 'sales_credit_note' then 'CRN'\n    when 'sales_debit_note'  then 'DBN'\n    when 'purchase_invoice'  then 'PUR'\n    when 'receipt'           then 'RCT'\n    when 'payment'           then 'PAY'\n  end;\nbegin\n  return format('%s-%s-%s', v_prefix, v_year,\n                lpad(app.next_number(p_tenant, p_type::text, v_year)::text, 6, '0'));\nend;\n$$;\n"}];
